import{_ as t,o as i,c as s,a4 as r}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse(`{"title":"ADR-0049 — Identité visuelle du site public : affichage adaptatif, polices auto-hébergées, couleurs harmonisées au contraste vérifié par l'API","description":"Extrait de docs/adr/0049-identite-visuelle-du-site-public.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0049 — Identité visuelle du site public : affichage adaptatif, polices auto-hébergées, couleurs harmonisées au contraste vérifié par l'API","description":"Extrait de docs/adr/0049-identite-visuelle-du-site-public.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0049-identite-visuelle-du-site-public.md","filePath":"developpeurs/adr/0049-identite-visuelle-du-site-public.md"}`),a={name:"developpeurs/adr/0049-identite-visuelle-du-site-public.md"};function o(l,e,n,u,c,d){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0049--identité-visuelle-du-site-public--affichage-adaptatif-polices-auto-hébergées-couleurs-harmonisées-au-contraste-vérifié-par-lapi" tabindex="-1">ADR-0049 — Identité visuelle du site public : affichage adaptatif, polices auto-hébergées, couleurs harmonisées au contraste vérifié par l&#39;API <a class="header-anchor" href="#adr-0049--identité-visuelle-du-site-public--affichage-adaptatif-polices-auto-hébergées-couleurs-harmonisées-au-contraste-vérifié-par-lapi" aria-label="Permalink to &quot;ADR-0049 — Identité visuelle du site public : affichage adaptatif, polices auto-hébergées, couleurs harmonisées au contraste vérifié par l&#39;API {#adr-0049--identité-visuelle-du-site-public--affichage-adaptatif-polices-auto-hébergées-couleurs-harmonisées-au-contraste-vérifié-par-lapi}&quot;">​</a></h1><p><strong>Date :</strong> 24 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> précise la décision n°3 (personnalisation) et n°4 (accessibilité) de l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0047-front-de-demarrage-optionnel">ADR-0047</a> ; RGAA 4.1 (critères 3.2 et 3.3 sur les contrastes, 10.4 sur le zoom, 10.11 sur la redistribution, 10.12 sur l&#39;espacement du texte) ; s&#39;appuie sur l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0020-attribution-de-licence-declaree-au-manifeste">ADR-0020</a> (attributions), l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0022-usine-a-sites-perimetre-du-provisionnement">ADR-0022</a> (usine à sites), l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0041-mediatheque-socle">ADR-0041</a> (médiathèque) et l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0046-profils-d-usage-a-l-installation">ADR-0046</a> (profils)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0047 promet un site public personnalisable sans code (logo, couleurs, polices, pied de page), avec un contraste vérifié à l&#39;enregistrement. Rien de cela n&#39;est construit.</p><p>Un site n&#39;a aujourd&#39;hui que quatre champs d&#39;identité : <code>logo_url</code>, <code>favicon_url</code>, <code>color_primary</code> et <code>color_secondary</code>. Ce sont des <strong>textes libres que rien ne valide</strong> : ni le format d&#39;une couleur, ni son contraste, ni l&#39;origine d&#39;un logo. Il n&#39;existe <strong>aucune règle d&#39;affichage</strong> sur mobile, tablette ou ordinateur, puisqu&#39;il n&#39;existe pas encore de site public. Il n&#39;y a <strong>aucune police</strong>.</p><p>Le Product Owner veut trois choses :</p><ul><li>un site qui s&#39;adapte au mobile, à la tablette et à l&#39;ordinateur ;</li><li>plusieurs polices au choix ;</li><li>des couleurs choisies sur une roue chromatique qui propose des accords, le tout réglable depuis le back-office.</li></ul><p>Pour un site de collectivité, ces libertés rencontrent deux contraintes :</p><ul><li><strong>le RGAA</strong>, puisqu&#39;un contraste trop faible rend le site non conforme ;</li><li><strong>le RGPD</strong> : une police chargée depuis les serveurs d&#39;un tiers lui transmet l&#39;adresse IP de chaque visiteur.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. L&#39;identité visuelle vit par site, dans un thème validé par l&#39;API.</strong></p><ul><li>Chaque site porte son thème, qui comprend : <ul><li>la couleur principale ;</li><li>l&#39;harmonie et la palette qui en découle ;</li><li>la police des titres et celle du texte ;</li><li>le logo et le favicon.</li></ul></li><li>Le schéma est validé par le Core, comme tout réglage.</li><li>Le logo et le favicon deviennent des <strong>médias de la médiathèque</strong> (ADR-0041), vérifiés au contenu, au lieu d&#39;URL libres.</li><li>Les champs <code>color_primary</code>, <code>color_secondary</code>, <code>logo_url</code> et <code>favicon_url</code> sont repris dans ce thème par une migration. Une valeur illisible n&#39;est pas recopiée, et la migration le dit.</li><li>L&#39;usine à sites (ADR-0022) transmet le thème du site modèle, et chaque site peut ensuite s&#39;en écarter.</li><li>L&#39;assistant IA d&#39;identité de site propose une couleur principale, qui passe par <strong>la même validation</strong>.</li></ul><p><strong>2. Les couleurs se choisissent sur une roue chromatique, par harmonie.</strong></p><ul><li>L&#39;administrateur choisit une couleur principale sur la roue, ou la saisit en hexadécimal. Il choisit ensuite une harmonie : complémentaire, analogue, triadique ou complémentaires adjacentes.</li><li>Le système en déduit la palette : couleur principale, couleur secondaire, couleur d&#39;accent, neutres, et leurs nuances. Les teintes et les nuances sont calculées dans l&#39;espace <strong>OKLCH</strong>, où un même écart de luminosité se perçoit de la même façon quelle que soit la teinte.</li><li>Les couleurs d&#39;état (erreur, succès, avertissement) ne dérivent pas de l&#39;harmonie. Leur sens doit rester reconnaissable, et elles sont vérifiées comme les autres.</li></ul><p><strong>3. L&#39;API vérifie les contrastes et propose une correction.</strong></p><ul><li>Le thème déclare les <strong>paires de couleurs réellement employées</strong> : texte sur fond, texte sur bouton principal, lien sur fond, contour de focus sur fond, etc.</li><li>L&#39;API calcule le contraste de chacune selon la formule de luminance relative du WCAG 2.1, que le RGAA reprend : <strong>4,5:1</strong> pour le texte courant, <strong>3:1</strong> pour le grand texte et les composants d&#39;interface.</li><li>Si une paire échoue, l&#39;API <strong>propose la nuance la plus proche qui passe</strong>, en gardant la teinte et en ne jouant que sur la luminosité. Elle <strong>refuse d&#39;enregistrer</strong> un thème qui contient une paire illisible.</li><li>Le calcul vit dans l&#39;API, pas dans le back-office. Tout front, livré ou tiers, reçoit un thème dont les contrastes sont garantis.</li><li>Une route d&#39;<strong>aperçu</strong> calcule la palette et les contrastes sans rien enregistrer. La roue s&#39;en sert à chaque changement.</li></ul><p><strong>4. Les polices viennent d&#39;une liste de 10 à 15 polices libres, hébergées par le front.</strong></p><ul><li>Les fichiers de police sont <strong>servis par le front lui-même</strong>. Aucune police n&#39;est chargée depuis un tiers, et donc aucune adresse IP de visiteur ne part chez Google ou ailleurs.</li><li>La liste comprend au moins deux polices conçues pour la lisibilité (par exemple Luciole et Atkinson Hyperlegible) et des polices courantes, avec et sans empattement. L&#39;administrateur choisit séparément la police des titres et celle du texte. Des paires recommandées lui sont proposées, avec un aperçu en direct.</li><li><strong>Chaque licence est vérifiée une par une à la livraison</strong>, et une attribution requise entre au registre de l&#39;ADR-0020.</li><li>Pour limiter le poids, on ne garde que deux ou trois graisses par police, en woff2, avec les caractères du latin étendu (accents et signes du français).</li><li>La police Marianne <strong>n&#39;est pas proposée</strong> : elle est réservée aux sites de l&#39;État.</li><li>L&#39;import de sa propre police est écarté en v1 (voir les alternatives).</li></ul><p><strong>5. Règles d&#39;affichage adaptatif du front, vérifiées automatiquement.</strong></p><ul><li>On conçoit d&#39;abord pour le mobile, puis on élargit. Trois gabarits : <strong>mobile</strong> en dessous de 640 px, <strong>tablette</strong> de 640 à 1 023 px, <strong>ordinateur</strong> à partir de 1 024 px.</li><li>Les colonnes du Page Builder se replient en une seule colonne sur mobile. Sur tablette, une colonne étroite rejoint sa voisine.</li><li>Les exigences du RGAA : <ul><li>lisible à <strong>320 px</strong> de large sans défilement horizontal (critère 10.11) ;</li><li>agrandissement du texte à <strong>200 %</strong> sans perte (10.4) ;</li><li>tailles en unités relatives, et texte courant à 16 px au moins par défaut ;</li><li>espacement du texte modifiable par le visiteur sans casse (10.12) ;</li><li>zones cliquables d&#39;<strong>au moins 24 px</strong> (WCAG 2.2, critère 2.5.8), et <strong>44 px visés</strong> pour les commandes principales et la navigation.</li></ul></li><li>La CI vérifie chaque thème aux trois largeurs : captures d&#39;écran comparées, et axe sur chaque gabarit.</li></ul><p><strong>6. Chaque profil livre un thème par défaut.</strong> Un profil qui installe un front (ADR-0046) apporte sa palette et sa paire de polices, déjà vérifiées. L&#39;administrateur part d&#39;un site lisible, puis le personnalise.</p><p><strong>7. Pas de mode sombre en v1.</strong> Un seul thème clair, entièrement vérifié. Le mode sombre doublerait les contrôles de contraste et les vérifications d&#39;affichage. Il viendra après les quatre thèmes de l&#39;ADR-0047.</p><p><strong>8. L&#39;écran « Apparence » du back-office est lui-même accessible.</strong> Une roue chromatique ne s&#39;utilise pas au clavier. L&#39;écran offre donc aussi :</p><ul><li>une saisie hexadécimale ;</li><li>des curseurs de teinte, de saturation et de luminosité, utilisables au clavier et libellés.</li></ul><p>Chaque résultat de contraste est annoncé par un texte et une icône, jamais par la seule couleur. L&#39;aperçu montre des blocs types aux trois largeurs.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td>Couleurs libres, et un contraste insuffisant simplement signalé</td><td>Un site de collectivité pourrait devenir non conforme sans que personne ne le voie. Le RGAA n&#39;est pas une préférence.</td></tr><tr><td>Couleurs saisies sans harmonie, avec un simple contrôle de contraste</td><td>Plus simple à construire, mais aucune aide au choix, et c&#39;est justement ce que le Product Owner demande.</td></tr><tr><td>Contraste vérifié dans le back-office seulement</td><td>Un front tiers, ou un appel direct à l&#39;API, contournerait le contrôle. La règle du dépôt veut que le Core juge.</td></tr><tr><td>Harmonies calculées en TSL (HSL)</td><td>En TSL, deux couleurs de même « luminosité » n&#39;ont pas la même luminosité perçue : un jaune et un bleu au même réglage n&#39;ont rien de comparable. Les nuances dérivées tomberaient au hasard du contraste.</td></tr><tr><td>Catalogue Google Fonts</td><td>Plus d&#39;un millier de polices, impossibles à vérifier une par une (licence, accents, lisibilité). Les servir depuis Google enverrait l&#39;adresse IP de chaque visiteur à un tiers.</td></tr><tr><td>Import de sa propre police</td><td>Fidèle à une charte existante, mais la licence devient la responsabilité de l&#39;exploitant, et un fichier importé doit être vérifié. À rouvrir si une collectivité le demande.</td></tr><tr><td>Un thème par organisation</td><td>Un office de tourisme et une médiathèque d&#39;une même commune ne pourraient pas se distinguer.</td></tr><tr><td>Mode sombre dès la v1</td><td>Double les contrôles de contraste et d&#39;affichage avant même que le premier thème soit livré.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Tout site produit par Teuthis, par le front livré ou par un front tiers, reçoit un thème dont les contrastes sont garantis par l&#39;API.</li><li>Aucune police ne fait fuir l&#39;adresse IP des visiteurs.</li><li>Le logo passe par la médiathèque : type vérifié au contenu, SVG isolé, octets immuables.</li></ul><p><strong>Négatives</strong></p><ul><li>Une migration reprend les champs d&#39;identité existants. Une valeur illisible est abandonnée, et il faut le signaler à l&#39;exploitant.</li><li>La liste de polices est courte par choix. Une collectivité qui a une police de charte devra attendre l&#39;import, ou choisir la plus proche.</li><li><strong>La médiathèque ne produit aucune miniature</strong> (décision du lot 1, ADR-0041). Un site adaptatif sert des images trop lourdes au mobile tant que la médiathèque ne décline pas ses images par largeur. Cette question doit être tranchée avant le socle du front.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Thème de site dans le Core : schéma validé (couleur, harmonie, polices de la liste, logo et favicon de la médiathèque), migration des quatre champs existants, harmonies et nuances en OKLCH, contrastes WCAG 2.1 des paires déclarées, correction proposée, routes d&#39;aperçu et d&#39;enregistrement, exposition du thème dans l&#39;API publique ; usine à sites et assistant IA branchés sur le même schéma. — <code>app/theming/</code> (couleurs OKLCH et contraste WCAG 2.1, harmonies, échelles, rôles, paires déclarées <code>DECLARED_PAIRS</code>, correction par dichotomie, registre de 15 polices sans Marianne, thème par défaut conforme), <code>app/multisite/theme.py</code>, routes <code>app/api/site_theme.py</code> (<code>GET</code>/<code>PUT /sites/{id}/theme</code>, <code>POST …/theme/preview</code>, <code>GET /theme/catalogue</code>) et <code>GET /public/site-identity/theme</code> ; logo et favicon comptés comme usages de la médiathèque ; usine à sites et assistant IA sur la même validation ; migration <code>0037</code> (couleurs lisibles reprises, illisibles signalées, <code>color_primary</code>/<code>color_secondary</code> supprimées, <code>logo_url</code>/<code>favicon_url</code> gardées en repli) ; recette <code>tests/test_theming.py</code>, <code>tests/test_theme_de_site.py</code>, <code>tests/test_theme_de_site_migration.py</code>.</li><li>[x] Écran « Apparence » du back-office : roue chromatique, saisie hexadécimale et curseurs accessibles, choix de l&#39;harmonie, résultats de contraste annoncés en texte, choix des polices avec aperçu, aperçu aux trois largeurs. <strong>Partiel (audit du 26/09/2026, SUIVI-6)</strong> : les relais du BFF sont en place (<code>apps/admin/server/api/sites/[id]/theme/index.get.ts</code>, <code>index.put.ts</code>, <code>preview.post.ts</code>, <code>apps/admin/server/api/theme/catalogue.get.ts</code>) avec leurs types (<code>apps/admin/types/api.ts</code>, <code>ThemeInput</code>, <code>ThemeHarmonyKey</code>) . <strong>Page livrée le 30/09/2026</strong> : <code>apps/admin/pages/multisite/apparence.vue</code> (roue <code>components/theme/ColorWheel.vue</code> doublée d&#39;un champ hexadécimal, du sélecteur natif et de trois curseurs libellés ; contrastes annoncés en texte avec la correction de l&#39;API applicable d&#39;un bouton ; polices avec aperçu ; logo et favicon par <code>MediaPicker</code> ; aperçu aux trois largeurs <code>components/theme/ThemePreview.vue</code>). Contrôles au clavier et au lecteur d&#39;écran à faire dans un navigateur.</li><li>[ ] Liste des polices : sélection, licence vérifiée pour chacune, fichiers woff2 limités au latin étendu embarqués dans le front, attributions au registre (ADR-0020).</li><li>[ ] Règles d&#39;affichage adaptatif dans le socle du front, et CI aux trois largeurs (captures comparées, axe).</li><li>[ ] Thème par défaut de chaque profil (palette et paire de polices).</li><li>[ ] Trancher les déclinaisons d&#39;images par largeur, qui rouvrent la décision « pas de miniatures » de l&#39;ADR-0041, avant le socle du front.</li><li>[ ] <em>(Conditionnelle)</em> Mode sombre, après les quatre thèmes de l&#39;ADR-0047.</li></ul>',34)])])}const h=t(a,[["render",o]]);export{m as __pageData,h as default};
